 questions jsonb := $q$[{"n":1,"marks":1,"text":"Make the heading row A1:M1 Bold, give it Yellow fill colour and apply Wrap Text.","solution":"1. Select **A1:M1** (click A1, hold Shift, click M1).\n2. HOME → **Bold** (Ctrl+B).\n3. HOME → **Fill Color ▾** → Standard Colors → **Yellow**.\n4. HOME → **Wrap Text**.\n\nChecked: every heading cell A1 to M1 is bold, yellow and wrapped.","criteria":[{"rule":"cells","range":"A1:M1","props":{"bold":[true],"fillColor":["FFFF00"],"wrap":[true]}}]},{"n":2,"marks":1,"text":"In column K (Total) find the Total of Hindi, English, Computer and Rajasthan GK (F to I) for every student using the SUM function.","solution":"1. Click **K2** and type **=SUM(F2:I2)** → Enter (Rajnish Sharma: 78+64+91+70 = 303).\n2. Click K2 again and **double-click the fill handle** (small square at the bottom-right of the cell) to copy the formula down to **K201**.\n\nWhy SUM and not =F2+G2+H2+I2? Some students were absent in English (**AB**). The + sign gives **#VALUE!** when a cell has text, but SUM skips text, so Pooja Meena (row 3) gets 92+66+58 = 216.\n\nChecked: a formula in every cell K2:K201 with the right total.","criteria":[{"column":"K"}]},{"n":3,"marks":1,"text":"In column L (Percentage) find the percentage of every student. Each subject is out of 100, so the maximum total is 400 (Percentage = Total ÷ 400).","solution":"Excel's Percentage rule has two valid stages, and either earns the marks here:\n1. **Just the number, no % symbol**: type **=K2/400*100** → Enter (303 ÷ 400 × 100 = 75.75). This stores the plain number 75.75.\n2. **With the % symbol (recommended, since question 8 asks you to apply Percentage format to this same column)**: type **=K2/400** → Enter (303 ÷ 400 = 0.7575). This stores the **fraction**. On its own it displays as 0.7575 (General format) -- question 8 is where you apply the % format on top of it, which is what turns 0.7575 into **75.75%** (Percentage format always multiplies the stored value by 100 for display).\n\nDouble-click the fill handle of L2 either way to fill down to L201.\n\n⚠️ Do not mix the two: if you already multiplied by 100 (step 1) and then also apply Percentage format in question 8, Excel will multiply by 100 **again** on display and show something like 7575.00% -- wrong. Pick one method and use it for both question 3 and question 8.\n\nChecked: every cell in L2:L201 (either the plain number or the fraction).","criteria":[{"column":"L","alsoFraction":true}]},{"n":4,"marks":2,"text":"In column M (Result) using IF function write \"PASS\" if the Total is 160 or more (>=160), otherwise write \"FAIL\".","solution":"IF checks a condition: **=IF(condition, value if TRUE, value if FALSE)**. Text answers go inside double quotes.\n1. Click **M2** and type **=IF(K2>=160,\"PASS\",\"FAIL\")** → Enter.\n2. Double-click the fill handle to fill down to **M201**.\n\nComparison signs in Excel: **>** greater than, **<** less than, **>=** greater than or equal, **<=** less than or equal, **=** equal, **<>** not equal.\n\nChecked: PASS/FAIL in every cell M2:M201 (capital or small letters both count).","criteria":[{"column":"M"}]},{"n":5,"marks":2,"text":"In cell T2 find the total number of students using COUNTA on Student Name (B2:B201), and in cell T3 find how many students appeared in English using COUNT on G2:G201.","solution":"**COUNTA** counts every cell that is not empty (text and numbers). **COUNT** counts only cells with numbers.\n1. **T2**: =COUNTA(B2:B201) → 200.\n2. **T3**: =COUNT(G2:G201) → 183 (the 17 students marked AB are text, so COUNT leaves them out).\n\nAlso useful: **COUNTBLANK** counts empty cells.\n\nChecked: T2 and T3, both with formulas.","criteria":[{"rule":"value","cell":"T2","equals":200,"formula":true},{"rule":"value","cell":"T3","equals":183,"formula":true}]},{"n":6,"marks":1,"text":"Select M2:M201 and with Conditional Formatting highlight the cells equal to \"FAIL\" with Light Red Fill with Dark Red Text.","solution":"1. Select **M2:M201** (click M2, then press **Ctrl+Shift+↓**).\n2. HOME → **Conditional Formatting ▾** → **Highlight Cells Rules** → **Equal To...**\n3. Type **FAIL**, keep **Light Red Fill with Dark Red Text** → **OK**.\n\n(Highlight Cells Rules → Text that Contains... with FAIL also counts.)\n\nChecked: the rule on M2:M201.","criteria":[{"rule":"anyOf","criteria":[{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"equalTo","value":"FAIL","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"equalTo","value":"Fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"equalTo","value":"fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"textContains","value":"FAIL","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"textContains","value":"Fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M2:M201","type":"textContains","value":"fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"equalTo","value":"FAIL","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"equalTo","value":"Fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"equalTo","value":"fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"textContains","value":"FAIL","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"textContains","value":"Fail","style":"lightRedDarkRed"}},{"rule":"sheet","path":"conditionalFormats","includes":{"range":"M1:M201","type":"textContains","value":"fail","style":"lightRedDarkRed"}}]}]},{"n":7,"marks":1,"text":"Apply Filter to the complete table A1:M201.","solution":"1. Click any cell of the table, for example **A1**.\n2. DATA → **Filter** (or HOME → Sort & Filter ▾ → Filter, or **Ctrl+Shift+L**). Arrow buttons appear in the heading row.\n\nDo this after the formula columns are filled, so the filter covers A1:M201.\n\nChecked: a filter on the table.","criteria":[{"rule":"sheet","path":"filter","in":["A1:J201","A1:K201","A1:L201","A1:M201"]}]},{"n":8,"marks":2,"text":"Apply Percentage Number Format with 2 decimal places to the Percentage column L2:L201.","solution":"Percentage Number Format does not change the stored value -- it multiplies it by 100 **for display** and adds a % sign. That only looks right if L already holds the **fraction** (0.7575, from question 3's =K2/400).\n1. Select **L2:L201** (click L2, then **Ctrl+Shift+↓**).\n2. Right-click → **Format Cells** (Ctrl+1) → **Number** → **Percentage** → 2 decimal places → **OK**.\n\n(The % button plus Increase Decimal twice also works.)\n\nIf question 3 was answered with the plain-number method (=K2/400*100, giving 75.75) instead, applying this format will show 7575.00% -- change L's formula to =K2/400 first so it shows 75.75% correctly.\n\nChecked: L2:L201 in Percentage format with 2 decimals.","criteria":[{"rule":"cells","range":"L2:L201","props":{"numberFormat":["Percentage"],"decimals":[2]}}]},{"n":9,"marks":2,"text":"Apply All Borders to the complete table A1:M201.","solution":"1. Select **A1:M201** (click A1, then **Ctrl+Shift+→** and **Ctrl+Shift+↓**).\n2. HOME → **Borders ▾** → **All Borders**.\n\nChecked: every cell A1:M201 has borders on all four sides.","criteria":[{"rule":"cells","range":"A1:M201","props":{"border":["trbl"]}}]},{"n":10,"marks":2,"text":"Apply AutoFit Column Width to the columns A to M, and Center alignment to the Gender column C2:C201.","solution":"1. Select the columns **A to M** (click column letter A, hold Shift, click M).\n2. HOME → **Format ▾** → **AutoFit Column Width**.\n3. Select **C2:C201** and click HOME → **Center** (Ctrl+E).\n\n(Double-clicking the line between two column letters also does AutoFit.)\n\nChecked: AutoFit on columns A to M, and C2:C201 centred.","criteria":[{"rule":"sheet","path":"autoFitCols","includesAll":["A","B","C","D","E","F","G","H","I","J","K","L","M"]},{"rule":"cells","range":"C2:C201","props":{"align":["center"]}}]},{"n":11,"marks":2,"text":"Freeze the Top Row of the sheet, and rename the sheet Sheet1 to \"Students\".","solution":"1. VIEW → **Freeze Panes ▾** → **Freeze Top Row**.\n2. **Right-click** the sheet tab **Sheet1** (bottom-left) → **Rename**, type **Students** → Enter.\n\nChecked: panes frozen below row 1, and the sheet name is Students.","criteria":[{"rule":"sheet","path":"freeze","equals":"A2"},{"rule":"sheet","path":"name","equals":"Students"}]},{"n":12,"marks":2,"text":"Give the heading row A1:M1 a Dark Blue font colour and Font Size 12, in addition to the Bold, Yellow fill and Wrap Text from question 1.","solution":"1. Select **A1:M1**.\n2. HOME → **Font Color ▾** → Standard Colors → **Dark Blue**.\n3. HOME → **Font Size** box → type **12** → Enter.\n\nChecked: A1:M1 has a dark blue font colour and font size 12.","criteria":[{"rule":"cells","range":"A1:M1","props":{"fontColor":["1F3864","002060","1F4E78"],"fontSize":[12]}}]},{"n":13,"marks":2,"text":"Apply Italic to the Category column E2:E201, and Center alignment to the Rajasthan GK column I2:I201.","solution":"1. Select **E2:E201** and click HOME → **Italic** (Ctrl+I).\n2. Select **I2:I201** (the Rajasthan GK column) and click HOME → **Center** (Ctrl+E).\n\nChecked: E2:E201 italic, I2:I201 centred.","criteria":[{"rule":"cells","range":"E2:E201","props":{"italic":[true]}},{"rule":"cells","range":"I2:I201","props":{"align":["center"]}}]},{"n":14,"marks":2,"text":"Give the sheet tab a Blue Tab Color, and Bold the Total column K2:K201.","solution":"1. **Right-click** the sheet tab → **Tab Color** → Standard Colors → **Blue**.\n2. Select **K2:K201** and click HOME → **Bold** (Ctrl+B).\n\nChecked: the tab colour is blue, and K2:K201 is bold.","criteria":[{"rule":"sheet","path":"tabColor","equals":["0070C0","2E75B6","1F4E78"]},{"rule":"cells","range":"K2:K201","props":{"bold":[true]}}]},{"n":15,"marks":2,"text":"Apply Number Format with 0 decimal places to the Typing Speed column J2:J201, and Center alignment to J2:J201.","solution":"1. Select **J2:J201**.\n2. Right-click → **Format Cells** (Ctrl+1) → **Number** → **Number** → 0 decimal places → **OK**.\n3. HOME → **Center** (Ctrl+E).\n\nChecked: J2:J201 with 0 decimals and centred.","criteria":[{"rule":"cells","range":"J2:J201","props":{"numberFormat":["Number","General"],"decimals":[0],"align":["center"]}}]}]$q$::jsonb;
 cells jsonb; model_cells jsonb; working jsonb; model jsonb;
begin
 select coalesce(max(version_number), 0) + 1 into next_version from public.excel_efficiency_versions where test_id = t_id;
 if next_version <> 3 then raise notice 'EXCEL EFFICIENCY TEST 4 already has version %, skipping', next_version; return; end if;

 select jsonb_object_agg(ref, cell) into cells from (
   select chr(65 + i) || '1' as ref, pg_temp.excel_cell(headers->i) as cell from generate_series(0, jsonb_array_length(headers) - 1) i
   union all select chr(65 + i) || (r + 2), pg_temp.excel_cell(students->r->i) from generate_series(0, jsonb_array_length(students) - 1) r, generate_series(0, 9) i
   union all select s->>0, pg_temp.excel_cell(s->1) from jsonb_array_elements(summary) s) x;
 working := jsonb_build_object('schemaVersion', 1, 'language', 'English', 'rows', 201, 'cols', 20, 'cells', cells);
 perform public.assert_excel_efficiency_working_matter(working);

 select cells || jsonb_object_agg(ref, cell) into model_cells from (
   select t.key || (r + 2) as ref, pg_temp.excel_cell(vals->t.key->r, replace(t.value, '#', (r + 2)::text)) as cell from jsonb_each_text(templates) t, generate_series(0, 199) r
   union all select key, pg_temp.excel_cell(value->1, value->>0) from jsonb_each(summary_formulas)) x;

 -- Q1 + "dark blue / 12pt" question: header row style
 select model_cells || jsonb_object_agg(chr(65 + i) || '1', (model_cells->(chr(65 + i) || '1')) || '{"bold":true,"fillColor":"FFFF00","wrap":true,"fontColor":"1F3864","fontSize":12}'::jsonb)
   into model_cells from generate_series(0, jsonb_array_length(headers) - 1) i;
 -- "All Borders" question: every cell of the table A1:M201
 select model_cells || jsonb_object_agg(chr(65 + i) || r, (model_cells->(chr(65 + i) || r)) || '{"border":"trbl"}'::jsonb)
   into model_cells from generate_series(1, 201) r, generate_series(0, jsonb_array_length(headers) - 1) i;
 -- "Percentage format" question: L2:L201 (L already holds the fraction, so this correctly shows 75.75%)
 select model_cells || jsonb_object_agg('L' || r, (model_cells->('L' || r)) || '{"numberFormat":"Percentage","decimals":2}'::jsonb)
   into model_cells from generate_series(2, 201) r;
 -- "Number format + center" question: J2:J201
 select model_cells || jsonb_object_agg('J' || r, (model_cells->('J' || r)) || '{"numberFormat":"Number","decimals":0,"align":"center"}'::jsonb)
   into model_cells from generate_series(2, 201) r;
 -- "AutoFit + center Gender" question: C2:C201
 select model_cells || jsonb_object_agg('C' || r, (model_cells->('C' || r)) || '{"align":"center"}'::jsonb)
   into model_cells from generate_series(2, 201) r;
 -- "Italic Category + center Rajasthan GK" question: E2:E201, I2:I201 (fixed from H2:H201 / Computer)
 select model_cells || jsonb_object_agg('E' || r, (model_cells->('E' || r)) || '{"italic":true}'::jsonb)
   into model_cells from generate_series(2, 201) r;
 select model_cells || jsonb_object_agg('I' || r, (model_cells->('I' || r)) || '{"align":"center"}'::jsonb)
   into model_cells from generate_series(2, 201) r;
 -- "Tab Color + bold Total" question: K2:K201
 select model_cells || jsonb_object_agg('K' || r, (model_cells->('K' || r)) || '{"bold":true}'::jsonb)
   into model_cells from generate_series(2, 201) r;

 model := jsonb_build_object('schemaVersion', '3', 'rows', 201, 'cols', 20, 'cells', model_cells, 'merges', '[]'::jsonb,
   'sheet', $q${"name":"Students","freeze":"A2","filter":"A1:M201","filterHidden":{},"autoFitCols":["A","B","C","D","E","F","G","H","I","J","K","L","M"],"conditionalFormats":[{"range":"M2:M201","type":"equalTo","value":"FAIL","style":"lightRedDarkRed"}],"tabColor":"0070C0"}$q$::jsonb, 'operations', '[]'::jsonb, 'savedAt', '2026-11-10T00:00:00.000Z');
 perform public.assert_excel_efficiency_document_schema(model);

 insert into public.excel_efficiency_versions (test_id, version_number, title, language, description, instructions_markdown, question_count, maximum_marks,
   duration_options, passing_marks, working_matter_snapshot, created_by, delivery_pdf, delivery_onscreen, student_question_toggle, model_answer_snapshot)
 values (t_id, 3, 'EFFICIENCY TEST 4', 'English', 'SUM, Percentage, IF, COUNTA/COUNT and everyday formatting on 200 students (fixes the Rajasthan GK column and the Percentage format chain from version 2)',
   $q$1. Carefully read the instructions and solve the questions accordingly.
2. All questions are mandatory.
3. The sheet has 200 students (rows 2 to 201). Fill a formula in row 2, then double-click the fill handle to copy it down to row 201.
4. **Maximum marks** and question-wise marks are shown with the questions.
5. Complete each task directly in the spreadsheet. Any method is fine (formula, drag and fill, Flash Fill or typing): the answer in the cells is what is checked.$q$, 15, 25, array[600, 900, 1200], 9,
   working, (select created_by from public.excel_efficiency_tests where id = t_id), false, true, true, model) returning id into v_id;
 update public.excel_efficiency_tests set current_version_id = v_id, current_version_number = 3 where id = t_id;

 for item in select value from jsonb_array_elements(questions) loop
  crit := '[]'::jsonb;
  for c in select value from jsonb_array_elements(item->'criteria') loop
   if not c ? 'column' then crit := crit || jsonb_build_array(c);
   elsif coalesce((c->>'alsoFraction')::boolean, false) then
    crit := crit || jsonb_build_array(jsonb_build_object('rule', 'anyOf', 'criteria', jsonb_build_array(
      jsonb_build_object('rule', 'allOf', 'criteria', pg_temp.column_checks(vals, c->>'column', 1)),
      jsonb_build_object('rule', 'allOf', 'criteria', pg_temp.column_checks(vals, c->>'column', 0.01)))));
   else crit := crit || pg_temp.column_checks(vals, c->>'column', 1);
   end if;
  end loop;
  insert into public.excel_efficiency_questions (version_id, question_number, instruction, marks, display_order, solution)
  values (v_id, (item->>'n')::int, item->>'text', (item->>'marks')::numeric, (item->>'n')::int, item->>'solution') returning id into q_id;
  insert into public.excel_efficiency_grading_rules (version_id, question_id, exact_target, expected_operation, expected_value, allocated_marks, additional_criteria)
  values (v_id, q_id, 'hand-written', 'rule-criteria', 'null'::jsonb, (item->>'marks')::numeric, crit);
 end loop;
end $mig$;

-- Check: the model answer scores the full marks of every question, the untouched sheet 0.
select q.question_number, q.marks,
  public.excel_efficiency_score_question(v.model_answer_snapshot, v.id, q.id, q.marks) as model,
  public.excel_efficiency_score_question(public.excel_efficiency_initial_editor_document(v.working_matter_snapshot), v.id, q.id, q.marks) as untouched
from public.excel_efficiency_tests t join public.excel_efficiency_versions v on v.id = t.current_version_id
join public.excel_efficiency_questions q on q.version_id = v.id where t.id = '48dd8076-8223-4887-a83e-4cdec34561fd' order by q.question_number;

commit;
